let generate_permutations nums =
  let n = List.length nums in
  let used = Array.make n false in
  let result = ref [] in
  let rec backtrack current =
    if List.length current = n then
      result := List.rev current :: !result
    else
      List.iteri (fun i x ->
        if not used.(i) then begin
          used.(i) <- true;
          backtrack (x :: current);
          used.(i) <- false
        end
      ) nums
  in
  backtrack [];
  !result

