let bfs start adj =
  let n = Array.length adj in
  let visited = Array.make n false in
  let queue = Queue.create () in
  visited.(start) <- true;
  Queue.push start queue;
  let order = ref [] in
  while not (Queue.is_empty queue) do
    let u = Queue.pop queue in
    order := u :: !order;
    List.iter (fun v ->
      if not visited.(v) then begin
        visited.(v) <- true;
        Queue.push v queue
      end
    ) adj.(u)
  done;
  List.rev !order

