type bst = Empty | Node of { value : int; left : bst; right : bst }

let rec insert tree x =
  match tree with
  | Empty -> Node { value = x; left = Empty; right = Empty }
  | Node n ->
      if x < n.value then Node { n with left = insert n.left x }
      else if x > n.value then Node { n with right = insert n.right x }
      else tree

let rec inorder tree acc =
  match tree with
  | Empty -> acc
  | Node n -> inorder n.left (n.value :: inorder n.right acc)

