let bubble_sort arr =
  let n = Array.length arr in
  let swapped = ref true in
  let pass = ref 0 in
  while !swapped do
    swapped := false;
    for i = 0 to n - 2 do
      if arr.(i) > arr.(i + 1) then begin
        let tmp = arr.(i) in
        arr.(i) <- arr.(i + 1);
        arr.(i + 1) <- tmp;
        swapped := true
      end
    done;
    incr pass
  done;
  !pass

