let shift_char c shift =
  let base = if c >= 'a' && c <= 'z' then 'a' else if c >= 'A' && c <= 'Z' then 'A' else c in
  if base = c then c
  else Char.chr ((Char.code c - Char.code base + shift) mod 26 + Char.code base)

let encrypt msg shift =
  String.map (fun c -> shift_char c shift) msg

