let append da x =
  (* نضاعف السعة عند الامتلاء لتقليل عمليات النسخ *)
  if da.size = Array.length da.data then begin
    let new_cap = max 1 (2 * Array.length da.data) in
    let new_data = Array.make new_cap x in
    Array.blit da.data 0 new_data 0 da.size;
    da.data <- new_data
  end;
  da.data.(da.size) <- x;
  da.size <- da.size + 1

