  else begin
    let dp = Array.make (n + 1) 0 in
    dp.(0) <- 0;
    dp.(1) <- 1;
    for i = 2 to n do
      dp.(i) <- dp.(i - 1) + dp.(i - 2)
    done;
    dp.(n)
  end

