let quicksort arr =
  let rec sort lo hi =
    if lo < hi then begin
      let pivot = arr.(hi) in
      let i = ref lo in
      for j = lo to hi - 1 do
        if arr.(j) <= pivot then begin
          let tmp = arr.(!i) in
          arr.(!i) <- arr.(j);
          arr.(j) <- tmp;
          incr i
        end
      done;
      let tmp = arr.(!i) in
      arr.(!i) <- arr.(hi);
      arr.(hi) <- tmp;
      let p = !i in
      sort lo (p - 1);
      sort (p + 1) hi
    end
  in
  sort 0 (Array.length arr - 1)

